def esc(s): return html.escape(str(s), quote=True)
def path_url(lang,rel=''): return f'{BASE}/{lang}/'+rel.lstrip('/')
def alternates(rel=''):
    return ''.join(f'<link rel="alternate" hreflang="{l}" href="{path_url(l,rel)}">' for l in LANGS)+f'<link rel="alternate" hreflang="x-default" href="{path_url("en",rel)}">'
def nav(lang):
    t=T[lang]
    links=''.join(f'<a href="/{l}/">{NAMES[l]}</a>' for l in LANGS)
    return f'<div class="top"><div class="wrap topin">{links}</div></div><div class="nav"><div class="wrap navin"><a class="brand" href="/{lang}/">TABAC LUXE<small>TOBACCO & ALCOHOL WHOLESALE</small></a><div class="menu"><a href="/{lang}/">{t["home"]}</a><a href="/{lang}/catalog/">{t["catalog"]}</a><a href="/{lang}/tobacco/">{t["tobacco"]}</a><a href="/{lang}/alcohol/">{t["alcohol"]}</a><a href="/{lang}/about/">{t["about"]}</a><a href="/{lang}/contact/">{t["contact"]}</a></div><div class="tools"><button class="pill" data-open-cart>{t["enquiry"]} (<span data-count>0</span>)</button></div></div></div>'
def drawer(lang):
    return f'<aside id="drawer" class="drawer"><div class="drawerhead"><b>{T[lang]["enquiry"]}</b><button class="btn" data-close-cart>×</button></div><div id="cartBody" class="drawerbody"></div><div class="drawerfoot"><button class="btn gold" onclick="sendWA()">WhatsApp</button><button class="btn" onclick="sendMail()">Email</button></div></aside><a class="float-wa" href="javascript:sendWA()">WA</a><div class="toast"></div>'
def product_card(lang,p):
    return f'<article class="product" data-category="{esc(p["category"])}"><a class="prodimg" href="/{lang}/product/{p["slug"]}/"><div class="pack">{esc(p["brand"])}</div></a><div class="pbody"><div class="pbrand">{esc(p["brand"])}</div><h3><a href="/{lang}/product/{p["slug"]}/">{esc(p["name"])}</a></h3><div class="meta">{esc(p["size"])}</div><div class="price">{esc(p["price"])}</div><button class="btn" data-add data-slug="{esc(p["slug"])}" data-name="{esc(p["name"])}" data-size="{esc(p["size"])}" data-price="{esc(p["price"])}">{T[lang]["add"]}</button></div></article>'
def layout(lang,title,desc,rel,body):
    t=T[lang]; canonical=path_url(lang,rel)
    schema='{"@context":"https://schema.org","@type":"Organization","name":"Tabac Luxe","url":"'+BASE+'"}'
    return f'<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)}</title><meta name="description" content="{esc(desc)}"><meta name="keywords" content="{esc(t["seo"])}"><link rel="canonical" href="{canonical}">{alternates(rel)}<link rel="stylesheet" href="/assets/style.css"><script type="application/ld+json">{schema}</script></head><body>{nav(lang)}{body}{footer(lang)}{drawer(lang)}<script src="/assets/app.js"></script></body></html>'
def footer(lang):
    t=T[lang]
    return f'<footer class="footer"><div class="wrap footgrid"><div><div class="brand">TABAC LUXE<small>TOBACCO & ALCOHOL WHOLESALE</small></div><p>Luxembourg · Europe</p></div><div><h4>{t["catalog"]}</h4><ul><li><a href="/{lang}/tobacco/">{t["tobacco"]}</a></li><li><a href="/{lang}/alcohol/">{t["alcohol"]}</a></li></ul></div><div><h4>{t["about"]}</h4><ul><li><a href="/{lang}/about/">{t["about"]}</a></li><li><a href="/{lang}/contact/">{t["contact"]}</a></li></ul></div><div><h4>Europe</h4><p>{t["markets"]}</p></div></div><div class="wrap legal">© 2026 Tabac Luxe. B2B catalogue. No online checkout or payment.</div></footer>'
def write(rel,content):
    p=DIST/rel; p.parent.mkdir(parents=True,exist_ok=True); p.write_text(content,encoding='utf-8')

def grid(ps,lang): return '<div class="product-grid">'+''.join(product_card(lang,p) for p in ps)+'</div>'

