all_urls=[]
for lang in LANGS:
    t=T[lang]
    hero=f'<section class="hero" style="background:linear-gradient(90deg,rgba(0,0,0,.95),rgba(0,0,0,.65),rgba(0,0,0,.25)),url(/assets/luxury-hero.svg) center/cover"><div class="wrap"><div class="eyebrow">Luxembourg · Europe · {t["trade"]}</div><h1>{t["hero"]}</h1><p>{t["sub"]}</p><div class="actions"><a class="btn gold" href="/{lang}/catalog/">{t["browse"]}</a><a class="btn" href="/{lang}/contact/">{t["contact"]}</a></div><div class="trust"><span>Premium Brands</span><span>Trade Enquiries</span><span>Across Europe</span></div></div></section>'
    cats='<section class="category-strip"><div class="wrap categories">'+''.join(f'<a class="catcard" href="/{lang}/category/{c}/"><h3>{CATN[c]}</h3><span>{t["browse"]} →</span></a>' for c in ['cigarettes','whisky','vodka','beer'])+'</div></section>'
    body=hero+cats+f'<section class="section white"><div class="wrap"><div class="head"><div><div class="eyebrow">TABAC LUXE</div><h2>{t["featured"]}</h2></div><p>{t["markets"]}</p></div>{grid(products[:10],lang)}</div></section><section class="featureband"><div class="wrap featuregrid"><div><strong>Wide Range</strong><small>Tobacco, Alcohol & Accessories</small></div><div><strong>Trade Enquiries</strong><small>No online checkout</small></div><div><strong>Across Europe</strong><small>Cross-border B2B catalogue</small></div><div><strong>WhatsApp</strong><small>Fast enquiry handoff</small></div></div></section>'
    write(f'{lang}/index.html',layout(lang,f'Tabac Luxe | {t["hero"]}',t['sub'],'',body)); all_urls.append(path_url(lang,''))
    body=f'<section class="cataloghero"><div class="wrap"><div class="eyebrow">TABAC LUXE</div><h1>{t["catalog"]}</h1><p>{t["sub"]}</p></div></section><section class="section"><div class="wrap"><div class="filters"><input id="q" placeholder="{t["search"]}"><select id="catFilter"><option value="">{t["all"]}</option>'+''.join(f'<option value="{c}">{CATN[c]}</option>' for c in CATS)+'</select></div>'+grid(products,lang)+'</div></section>'
    write(f'{lang}/catalog/index.html',layout(lang,f'{t["catalog"]} | Tabac Luxe',t['sub'],'catalog/',body)); all_urls.append(path_url(lang,'catalog/'))
    for section,types in [('tobacco',{'Tobacco'}),('alcohol',{'Alcohol & Drinks'})]:
        ps=[p for p in products if p['type'] in types]
        h=t[section]
        b=f'<section class="cataloghero"><div class="wrap"><div class="eyebrow">B2B · Luxembourg</div><h1>{h}</h1><p>{t["seo"]}</p></div></section><section class="section"><div class="wrap">{grid(ps,lang)}</div></section>'
        write(f'{lang}/{section}/index.html',layout(lang,f'{h} Wholesale Luxembourg | Tabac Luxe',t['seo'],f'{section}/',b)); all_urls.append(path_url(lang,f'{section}/'))
    for rel,h,ptext in [('about/',t['about_h'],t['about_p']),('contact/',t['contact_h'],t['contact_p'])]:
        b=f'<section class="cataloghero"><div class="wrap"><div class="eyebrow">TABAC LUXE</div><h1>{h}</h1></div></section><section class="section white"><div class="wrap content"><p>{ptext}</p><p>{t["seo"]}</p><div class="actions"><button class="btn gold" onclick="sendWA()">WhatsApp</button><button class="btn" onclick="sendMail()">Email</button></div></div></section>'
        write(f'{lang}/{rel}index.html',layout(lang,f'{h} | Tabac Luxe',ptext,rel,b)); all_urls.append(path_url(lang,rel))
    for c in CATS:
        ps=[p for p in products if p['category']==c]
        b=f'<section class="cataloghero"><div class="wrap"><div class="eyebrow">B2B Wholesale · Luxembourg</div><h1>{CATN[c]}</h1><p>{t["seo"]}</p></div></section><section class="section"><div class="wrap">{grid(ps,lang) if ps else "<p>Trade availability on request.</p>"}</div></section>'
        rel=f'category/{c}/'; write(f'{lang}/{rel}index.html',layout(lang,f'{CATN[c]} Wholesale Luxembourg | Tabac Luxe',t['seo'],rel,b)); all_urls.append(path_url(lang,rel))
    for p in products:
        rel=f'product/{p["slug"]}/'; desc=f'{p["name"]} {p["size"]}. B2B trade catalogue from Tabac Luxe Luxembourg. Enquire by WhatsApp or email; no online checkout.'
        b=f'<section class="cataloghero"><div class="wrap breadcrumb"><a href="/{lang}/catalog/">{t["catalog"]}</a> / {esc(p["name"])}</div><div class="wrap"><div class="eyebrow">{esc(p["brand"])}</div><h1>{esc(p["name"])}</h1><p>{esc(p["size"])}</p></div></section><section class="section white"><div class="wrap"><div class="product" data-category="{esc(p["category"])}" style="max-width:520px"><div class="prodimg"><div class="pack">{esc(p["brand"])}</div></div><div class="pbody"><div class="pbrand">{esc(p["brand"])}</div><h3>{esc(p["name"])}</h3><div class="meta">{esc(p["size"])}</div><div class="price">{esc(p["price"])}</div><button class="btn gold" data-add data-slug="{esc(p["slug"])}" data-name="{esc(p["name"])}" data-size="{esc(p["size"])}" data-price="{esc(p["price"])}">{t["add"]}</button></div></div><div class="content"><h2>Trade product information</h2><p>{esc(desc)}</p><p>{t["seo"]}</p></div></div></section>'
        write(f'{lang}/{rel}index.html',layout(lang,f'{p["name"]} Wholesale | Tabac Luxe Luxembourg',desc,rel,b)); all_urls.append(path_url(lang,rel))

